import { appendFileSync, existsSync, readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('.', import.meta.url));
const manifest = JSON.parse(readFileSync(new URL('./source-manifest.json', import.meta.url), 'utf8'));
const expected = new Map(manifest.sourceFiles.map(row => [path.resolve(root, row.path), row.sha256]));
const packages = new Map([
  ['@agent-teams/legacy-agent-host', path.resolve(root, 'packages/legacy-agent-host')],
  ['@agent-teams/task-change-ledger', path.resolve(root, 'packages/task-change-ledger')],
]);
const metadata = new Map([...packages].map(([name, directory]) => [name,
  JSON.parse(readFileSync(path.join(directory, 'package.json'), 'utf8'))]));
const transcript = path.resolve(root, 'resolution.jsonl');
function verify(filename) {
  const hash = expected.get(filename);
  if (!hash) throw new Error(`Owned source is missing from original manifest: ${filename}`);
  const actual = createHash('sha256').update(readFileSync(filename)).digest('hex');
  if (hash !== actual) throw new Error(`Owned source changed before resolution: ${filename}`);
}
function sourceTarget(filename) {
  for (const directory of packages.values()) {
    const dist = path.join(directory, 'dist') + path.sep;
    const src = path.join(directory, 'src') + path.sep;
    if (filename.startsWith(dist)) filename = src + filename.slice(dist.length);
    if (filename.startsWith(src) && filename.endsWith('.js')) {
      const candidate = filename.slice(0, -3) + '.ts';
      if (!existsSync(candidate)) throw new Error(`Original source counterpart is absent: ${candidate}`);
      filename = candidate;
    }
    if (filename.startsWith(src)) {
      verify(filename);
      return filename;
    }
  }
  return undefined;
}
function bareTarget(specifier) {
  for (const [name, directory] of packages) {
    if (specifier !== name && !specifier.startsWith(name + '/')) continue;
    const key = specifier === name ? '.' : '.' + specifier.slice(name.length);
    let target = metadata.get(name).exports[key];
    if (target && typeof target === 'object') target = target.import ?? target.default;
    if (typeof target !== 'string') throw new Error(`Unmapped original workspace export: ${specifier}`);
    return sourceTarget(path.resolve(directory, target));
  }
}
export async function resolve(specifier, context, nextResolve) {
  let filename = bareTarget(specifier);
  if (!filename && (specifier.startsWith('.') || specifier.startsWith('file:')) && context.parentURL?.startsWith('file:')) {
    const url = new URL(specifier, context.parentURL);
    url.search = '';
    url.hash = '';
    filename = sourceTarget(fileURLToPath(url));
  }
  const result = await nextResolve(filename ? pathToFileURL(filename).href : specifier, context);
  if (result.url.startsWith('file:')) {
    const resolved = fileURLToPath(new URL(result.url));
    if (resolved.includes('/packages/legacy-agent-host/') || resolved.includes('/packages/task-change-ledger/')) {
      if (!resolved.startsWith(root)) throw new Error(`Foreign workspace resolution refused: ${resolved}`);
    }
    if (expected.has(resolved)) verify(resolved);
  }
  if (filename) appendFileSync(transcript, JSON.stringify({ pid: process.pid, specifier,
    parentURL: context.parentURL, source: path.relative(root, filename), sha256: expected.get(filename) }) + '\n');
  return result;
}

